from ortools.sat.python import cp_model
import json

def main():
    model = cp_model.CpModel()

    T = 50
    towers = list(range(1, T + 1))

    C = set()

    for i in range(1, 7):
        for j in range(i + 1, 7):
            C.add((i, j))

    for i in range(7, 11):
        for j in range(i + 1, 11):
            C.add((i, j))
    for i in range(7, 11):
        for j in range(11, 17):
            C.add((i, j))

    for i in range(11, 17):
        for j in range(i + 1, 17):
            C.add((i, j))
    for i in range(11, 17):
        for j in [8, 9, 10, 7, 1]:
            C.add((i, j))

    for i in range(17, 22):
        C.add((i, i + 1))
        C.add((i + 1, i))

    for i in range(23, 29):
        for j in range(i + 1, 29):
            C.add((i, j))

    for i in range(29, 34):
        C.add((i, i + 1))
        C.add((i + 1, i))

    for j in [17, 21, 24, 27, 30, 33]:
        C.add((35, j))

    for i in range(36, 41):
        for j in range(i + 1, 41):
            C.add((i, j))

    for i in range(41, 46):
        for j in range(i + 1, 46):
            C.add((i, j))
    for i in range(41, 46):
        for j in range(46, 51):
            C.add((i, j))

    cross_pairs = [(36, 41), (41, 46), (17, 36), (22, 41), (25, 46), 
                   (30, 47), (34, 50)]
    for i, j in cross_pairs:
        C.add((i, j))

    seq1 = [7, 17, 27, 37, 47, 3]
    for i in range(len(seq1) - 1):
        C.add((seq1[i], seq1[i + 1]))

    seq2 = [8, 18, 28, 38, 48, 5]
    for i in range(len(seq2) - 1):
        C.add((seq2[i], seq2[i + 1]))

    seq3 = [5, 15, 25, 2]
    for i in range(len(seq3) - 1):
        C.add((seq3[i], seq3[i + 1]))

    cross_pairs_12 = [(1, 35), (3, 41), (5, 46), (2, 36), (4, 50),
                     (6, 47), (7, 40), (10, 45), (13, 42), (16, 48)]
    for i, j in cross_pairs_12:
        C.add((i, j))

    ranges_13 = [(17, 22), (20, 25), (23, 28), (26, 31), (29, 34)]
    for start, end in ranges_13:
        for i in range(start, end + 1):
            for j in range(i + 1, end + 1):
                C.add((i, j))

    extra_pairs_13 = [(18, 24), (21, 27), (19, 30), (33, 19)]
    for i, j in extra_pairs_13:
        C.add((i, j))

    ranges_14 = [(37, 42), (38, 43), (39, 44), (40, 45)]
    for start, end in ranges_14:
        for i in range(start, end + 1):
            for j in range(i + 1, end + 1):
                C.add((i, j))

    reciprocal_14 = [(46, 36), (47, 41), (48, 37), (49, 42), (50, 38)]
    for i, j in reciprocal_14:
        C.add((i, j))

    cross_pairs_15 = [(1, 17), (1, 25), (2, 19), (2, 27), (3, 21), (3, 29),
                     (4, 23), (4, 31), (5, 18), (5, 26), (6, 20), (6, 28)]
    for i, j in cross_pairs_15:
        C.add((i, j))

    for i in range(7, 17):
        for j in range(i + 1, 17):
            C.add((i, j))

    extra_pairs_16 = [(7, 12), (7, 14), (8, 13), (8, 15), (9, 16), (9, 11),
                     (10, 11), (10, 13), (11, 16), (12, 15), (14, 7), (15, 8)]
    for i, j in extra_pairs_16:
        C.add((i, j))

    f = {}
    for i in towers:
        f[i] = model.NewIntVar(1, T, f"f_{i}")

    z = {}
    for i in towers:
        for k in range(1, T + 1):
            z[(i, k)] = model.NewBoolVar(f"z_{i}_{k}")

    u = {}
    for k in range(1, T + 1):
        u[k] = model.NewBoolVar(f"u_{k}")

    for i in towers:
        model.Add(sum(z[(i, k)] for k in range(1, T + 1)) == 1)

    for i in towers:
        model.Add(f[i] == sum(k * z[(i, k)] for k in range(1, T + 1)))

    for i, j in C:
        model.Add(f[i] != f[j])

    for k in range(1, T + 1):
        for i in towers:
            model.Add(u[k] >= z[(i, k)])

    model.Minimize(sum(u[k] for k in range(1, T + 1)))

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 300.0
    solver.parameters.num_search_workers = 8
    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        freq_list = [solver.Value(f[i]) for i in range(1, T + 1)]
        used_frequencies = len(set(freq_list))
        print(json.dumps({"tower_frequencies": freq_list, "num_frequencies": used_frequencies}))
    else:
        print(json.dumps({"tower_frequencies": [], "num_frequencies": 0}))

if __name__ == "__main__":
    main()
